let partCategory='',partTypeFilter='',toolboxTab='Jobs',supplyQuery='',supplyCategory='',supplyArchived=false,supplyLow=false,inventoryPhoto='';
function itemVisual(p,large=false){return '<div class="item-visual '+(large?'large ':'')+(p.picture?'has-photo':'')+'" data-icon-colour="'+iconColour(p)+'">'+(p.picture?'<img src="'+esc(p.picture)+'" alt="'+esc(p.name)+'">':itemIcon(p))+'</div>';}
function categorySelect(name,label,value,values,blank=false){return '<label class="field">'+esc(label)+'<select name="'+name+'" id="'+name+'">'+(blank?'<option value="">All categories</option>':'')+values.map(v=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';}
function photoEditor(item){return '<div class="row mt"><div id="item-photo-preview">'+itemVisual({...item,name:'Selected photograph',picture:inventoryPhoto})+'</div>'+btn('Choose photograph','item-photo')+btn('Remove photograph','item-photo-remove')+'</div>';}
function partTypeInput(category,value=''){return field('partType','Part type',value,'text',[...(slotforgeCatalogue.parts[category]||[]),...db.parts.filter(p=>p.category===category).map(p=>p.partType).filter(Boolean)]);}
function editPart(id){const fromLibrary=page==='Library'&&libraryTab==='parts',revision=db.revision,p=id?db.parts.find(p=>p.id===id):{quantity:1,tracking:'quantity',condition:'New',category:partCategory||'Other & custom parts'};inventoryPhoto=p.picture||'';
modal(id?'Edit part':fromLibrary?'Add catalogue entry':'Add parts','<div class="form-grid">'+field('name','Part name',p.name||'','text',db.parts.map(p=>p.name))+categorySelect('category','Category',p.category,Object.keys(slotforgeCatalogue.parts))+'<div id="part-type-field">'+partTypeInput(p.category,p.partType||'')+'</div>'+field('maker','Manufacturer',p.maker||'','text',db.parts.map(p=>p.maker).filter(Boolean))+field('tracking','Tracking',p.tracking,'select',['quantity','individual'])+field('quantity','Owned quantity (individual pieces)',p.quantity,'number')+field('reference','Product reference / individual identifier',p.reference||'')+field('scale','Scale',p.scale||'','text',['1:24','1:32','1:43','HO'])+field('dimensions','Dimensions',p.dimensions||'')+field('material','Material / compound',p.material||'','text',db.parts.map(p=>p.material).filter(Boolean))+field('compatibility','Compatibility notes',p.compatibility||'')+field('condition','Condition',p.condition,'text',['New','Used','Needs inspection'])+field('location','Storage location',p.location||'','text',db.parts.map(p=>p.location))+field('notes','Notes',p.notes||'','textarea')+'</div>'+appearanceEditor(p)+photoEditor(p),async values=>{partId=await change('part.save',{id,revision,data:{...values,picture:inventoryPhoto}});if(fromLibrary){page='Library';libraryTab='parts';return;}page='Parts';partsTab='Stock';if(db.parts.find(p=>p.id===partId).quantity===0)stockScope='catalogue';partCategory=db.parts.find(item=>item.id===partId).category;partTypeFilter='';partQuery='';},'Save part');const quantityInput=$('#dialog [name=quantity]');quantityInput.required=true;quantityInput.step='1';}
let stockScope='owned';
const stockItems=()=>db.parts.filter(p=>stockScope!=='owned'||p.quantity>0);
function stockTabs(){return '<div class="tabs">'+[['owned','My stock'],['catalogue','Catalogue'],['shopping','Shopping list']].map(([id,name])=>'<button data-action="stock-scope" data-id="'+id+'" class="'+(id===stockScope?'active':'')+'">'+name+'</button>').join('')+'</div>';}
function partGroups(){return [...new Set([...Object.keys(slotforgeCatalogue.parts),...(db._view?.groups?.map(g=>g.category)||db.parts.map(p=>p.category))])];}
function partGroupCards(){return '<div class="part-group-grid '+(stockScope==='catalogue'?'catalogue-groups':'stock-groups')+'">'+partGroups().map(category=>{const items=stockItems().filter(p=>p.category===category),free=items.reduce((n,p)=>n+available(p),0),total=items.reduce((n,p)=>n+p.quantity,0),types=slotforgeCatalogue.parts[category]||[],g=db._view?.groups?.find(g=>g.category===category),count=g?.count??items.length,freeCount=g?.available??free,totalCount=g?.quantity??total;return '<button type="button" class="part-group-card '+(count?'':'is-empty')+'" data-action="part-group" data-id="'+esc(category)+'">'+itemVisual({category,partType:types[0]||''})+'<span class="part-group-copy"><strong>'+esc(category)+'</strong><span class="tiny muted">'+esc(types.slice(0,3).join(' · '))+(types.length>3?'…':'')+'</span></span><span class="part-group-arrow">'+icon('next')+'</span><span class="part-group-summary"><span class="badge">'+count+' part record'+(count===1?'':'s')+'</span><span class="tiny muted">'+(count?freeCount+' available · '+(totalCount-freeCount)+' fitted / reserved':'Ready for your first part')+'</span></span></button>';}).join('')+'</div>';}
function renderStock(tabs=''){
  if(!local())return empty('Inventory stays with its owner','Switch to your local database to manage parts.');
  if(stockScope==='shopping')return heading('Shopping list','Plan purchases, then record parts as they arrive.')+tabs+stockTabs()+shoppingList()+viewPager(db._view?.list);
  const searching=!!partQuery.trim(),folders=!partCategory&&!searching,list=stockItems().filter(p=>(!db._view?.partIds||db._view.partIds.includes(p.id))&&(!partCategory||p.category===partCategory)&&(!partTypeFilter||p.partType===partTypeFilter)&&[p.name,p.category,p.partType,p.maker,p.reference,p.location,p.compatibility].join(' ').toLowerCase().includes(partQuery.trim().toLowerCase())),p=folders?null:db.parts.find(p=>p.id===partId);
  const search='<label class="search">'+icon('search')+'<input id="part-search" value="'+esc(partQuery)+'" placeholder="Search all parts, references or locations…" aria-label="Search all parts"></label>';
  const head=heading('Parts','Owned stock and catalogue references, organised into main groups',btn(icon('plus')+' Add parts','add-part','primary'))+tabs+stockTabs();
  if(folders)return head+'<div class="toolbar">'+search+'</div><div class="section-heading"><h2>Main groups</h2><span class="muted tiny">'+(db._view?.groups?.reduce((n,g)=>n+g.count,0)??stockItems().length)+' part records · '+partGroups().length+' groups</span></div>'+partGroupCards()+'<p class="footer-note">Open a group to browse its parts. Counts show part records; stock quantities count individual pieces. Assemblies stay in their own tab.</p>';
  const filters='<div class="toolbar">'+search+categorySelect('part-category-filter','Group',partCategory,partGroups(),true)+'<label class="field">Part type<select id="part-type-filter"><option value="">All types</option>'+(db._view?.partTypes||[...new Set(db.parts.filter(p=>!partCategory||p.category===partCategory).map(p=>p.partType).filter(Boolean))].sort()).map(t=>'<option '+(t===partTypeFilter?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label></div>';
  const breadcrumb='<div class="part-breadcrumb">'+btn(icon('arrow')+' All groups','part-groups','small ghost')+'<span aria-hidden="true">/</span><strong>'+(searching?'Search results':esc(partCategory))+'</strong><span class="badge">'+(db._view?.list?.total??list.length)+' part record'+((db._view?.list?.total??list.length)===1?'':'s')+'</span></div>';
  const table=list.length?'<div class="table-wrap"><table><thead><tr><th>Part</th><th>Available</th><th>Fitted / reserved</th></tr></thead><tbody>'+list.map(p=>'<tr data-action="select-part" data-id="'+esc(p.id)+'" class="part-select-row '+(p.id===partId?'selected':'')+'"><td><div class="item-row">'+itemVisual(p)+'<div>'+btn(esc(p.name),'select-part','table-name',p.id)+'<div class="tiny muted">'+esc([searching?p.category:'',p.partType,p.reference,p.location].filter(Boolean).join(' · '))+'</div></div></div></td><td>'+available(p)+'</td><td>'+(p.quantity-available(p))+'</td></tr>').join('')+'</tbody></table></div>':empty(searching||partTypeFilter?'No matching parts':'This group is empty',searching||partTypeFilter?'Try another search or part type.':'Add a part to start filling this group.',btn('Add parts','add-part','primary'));
  return head+breadcrumb+filters+'<div class="part-layout '+(p?'':'no-selection')+'"><div>'+table+viewPager(db._view?.list)+'</div><div>'+(p?panel(p.name,itemVisual(p,true)+dl([['Category',p.category],['Type',p.partType],['Manufacturer',p.maker],['Reference',p.reference],['Scale',p.scale],['Dimensions',p.dimensions],['Material / compound',p.material],['Compatibility',p.compatibility],['Condition',p.condition],['Tracking',p.tracking],['Available',String(available(p))],['Location',p.location]])+catalogueDetails(p)+'<p class="prewrap">'+esc(p.notes)+'</p><div class="actions">'+stockEditAction(p)+purchaseStockActions(p)+btn('Icon & colour','part-appearance','',p.id)+(available(p)>0?btn('Install on car','install-stock','primary',p.id):'')+btn('Delete part…','delete-part','danger',p.id)+'</div><h3 class="mt">Installation history</h3>'+db.installations.filter(i=>i.partId===p.id).map(i=>'<div class="list-row"><div>'+esc(db.cars.find(c=>c.id===i.carId)?.name)+'<div class="tiny muted">'+i.quantity+' piece(s) · '+date(i.installed)+' · '+(i.removed?'Removed':'Installed')+'</div></div></div>').join('')+viewPager(db._view?.partHistory)):panel('Select a part','<p class="muted">Inspect its photograph, specifications and stock history.</p>'))+'</div></div><p class="footer-note">Stock quantities count individual pieces. Build ready-to-install assemblies in the Assemblies tab. Tools and consumables live in Workshop → Workshop supplies.</p>';
}

function toolboxTabs(){return '<div class="tabs">'+['Jobs','Workshop supplies','Manuals and Part Guides'].map(t=>'<button data-action="toolbox-tab" data-id="'+t+'" class="'+(toolboxTab===t?'active':'')+'">'+icon(t==='Jobs'?'tool':t==='Workshop supplies'?'box':'photos')+t+'</button>').join('')+'</div>';}
function renderWorkshop(){if(!local())return empty('Workshop records are local','Switch to your local database to use your toolbox.');if(workshopJob)return renderJob();return toolboxTab==='Manuals and Part Guides'?renderGuides():toolboxTab==='Workshop supplies'?renderSupplies():renderWorkshopJobs();}
const lowSupply=s=>s.kind==='Consumable'&&s.remaining!==null&&s.minimum!==null&&s.remaining<=s.minimum;
function supplyAmount(s){return s.kind==='Consumable'?(s.remaining===null?'Amount not recorded':s.remaining+' '+s.unit):s.quantity+' item(s)';}
function supplyCards(){const list=db.supplies.filter(s=>s.archived===supplyArchived&&(!supplyCategory||s.category===supplyCategory)&&(!supplyLow||lowSupply(s))&&[s.name,s.partType,s.maker,s.reference,s.location].join(' ').toLowerCase().includes(supplyQuery.toLowerCase()));return list.length?'<div class="toolbox-grid">'+list.map(s=>'<section class="panel"><div class="item-row">'+itemVisual(s)+'<div><h2>'+esc(s.name)+'</h2><div class="tiny muted">'+esc(s.category)+' · '+esc(s.partType||s.kind)+'</div></div></div><div class="row mt">'+badge(supplyAmount(s),lowSupply(s)?'low-stock':'')+(lowSupply(s)?badge('Low stock','low-stock'):'')+'</div>'+dl([['Quantity',String(s.quantity)],['Location',s.location],['Condition',s.condition],['Low-stock threshold',s.minimum===null?'Not set':s.minimum+' '+s.unit]])+catalogueDetails(s)+'<p class="prewrap muted">'+esc(s.notes)+'</p><div class="actions">'+btn(s.kind==='Consumable'?'Update amount / edit':'Edit item','edit-supply','small',s.id)+btn(s.archived?'Restore':'Archive…','archive-supply','small',s.id)+btn('Delete…','delete-supply','small danger',s.id)+'</div>'+(s.history.length?'<details class="mt"><summary>Amount history ('+s.history.length+')</summary>'+s.history.slice().reverse().map(h=>'<p class="tiny">'+date(h.date)+' · '+esc(supplyAmount(h.before))+' → '+esc(supplyAmount(h.after))+' · item quantity '+h.before.quantity+' → '+h.after.quantity+'</p>').join('')+'</details>':'')+'</section>').join('')+'</div>':empty('Your digital toolbox','Add tools and consumables, or adjust the filters.',btn('Add toolbox item','add-supply','primary'));}
function renderSupplies(){return heading('Workshop supplies','Tools, equipment and consumables, ready for your next session.',btn(icon('plus')+' Add toolbox item','add-supply','primary'))+toolboxTabs()+'<div class="toolbar"><label class="search">'+icon('search')+'<input id="supply-search" aria-label="Search toolbox" placeholder="Find tools or supplies…" value="'+esc(supplyQuery)+'"></label>'+categorySelect('supply-category-filter','Category',supplyCategory,Object.keys(slotforgeCatalogue.supplies),true)+'<label class="check-row"><input type="checkbox" id="supply-low" '+(supplyLow?'checked':'')+'>Low stock only</label><label class="check-row"><input type="checkbox" id="supply-archived" '+(supplyArchived?'checked':'')+'>Archived</label></div><div id="supply-results">'+supplyCards()+viewPager(db._view?.list)+'</div>';}
function editSupply(id){const revision=db.revision,s=id?db.supplies.find(s=>s.id===id):{category:'Hand tools',kind:'Tool / equipment',quantity:1,condition:'Good',remaining:null,minimum:null};inventoryPhoto=s.picture||'';
modal(id?'Edit toolbox item':'Add toolbox item','<div class="form-grid">'+field('name','Item name',s.name||'')+categorySelect('supply-category','Category',s.category,Object.keys(slotforgeCatalogue.supplies))+field('partType','Item type',s.partType||'','text',[...Object.values(slotforgeCatalogue.supplies).flat(),...db.supplies.map(s=>s.partType)])+field('kind','Kind',s.kind,'select',['Tool / equipment','Consumable'])+field('quantity','Item / container count',s.quantity,'number')+field('maker','Manufacturer',s.maker||'','text',db.supplies.map(s=>s.maker))+field('reference','Reference',s.reference||'')+field('location','Location',s.location||'','text',db.supplies.map(s=>s.location))+field('condition','Condition',s.condition,'text',['New','Good','Used','Needs repair'])+field('notes','Notes',s.notes||'','textarea')+'</div><section id="consumable-fields" class="mt" '+(s.kind==='Consumable'?'':'hidden')+'><p class="muted">Track the total remaining amount across your containers. Leave it blank if unknown; zero means empty.</p><div class="form-grid">'+field('remaining','Remaining amount',s.remaining??'','number')+field('unit','Amount unit',s.unit||'','text',['ml','g','pieces','bottles','metres','sheets'])+field('minimum','Low-stock threshold',s.minimum??'','number')+'</div><p class="tiny muted">Keep the same unit when updating amounts. Changes are retained in history.</p></section>'+appearanceEditor(s)+photoEditor(s),async values=>{await change('supply.save',{id,revision,data:{...values,category:values['supply-category'],picture:inventoryPhoto}});supplyQuery='';supplyCategory='';supplyLow=false;toolboxTab='Workshop supplies';page='Workshop';},'Save toolbox item');
for(const name of ['remaining','minimum']){const input=$('[name="'+name+'"]');input.step='any';input.min='0';}}
async function inventoryAction(action,id){switch(action){case 'part-groups':partCategory='';partTypeFilter='';partQuery='';partId=null;render();return true;case 'part-group':if(!partGroups().includes(id))return true;partCategory=id;partTypeFilter='';partQuery='';partId=null;render();return true;case 'part-appearance':editPartAppearance(id);return true;case 'delete-part':{const plan=await api('plan','part.delete',{id});if(plan.reasons.length){modal('This part is linked to your records','<p><strong>'+esc(plan.name)+'</strong> is referenced by '+esc(plan.reasons.join(', '))+'.</p><p>Keep this part record to preserve those links. Unused parts can be deleted.</p>',null);return true;}modal('Delete part?','<p>Permanently delete <strong>'+esc(plan.name)+'</strong> and its '+plan.quantity+' piece(s) of stock?</p><p>This cannot be undone here.</p>',async()=>{await change('part.delete',{id,revision:plan.revision});if(partId===id)partId=null;catalogueManagerSelected.delete(id);},'Delete part');return true;}case 'delete-supply':{const item=db.supplies.find(s=>s.id===id),revision=db.revision;modal('Delete workshop supply?','<p>Permanently delete <strong>'+esc(item.name)+'</strong>, its photograph and all '+item.history.length+' amount history entries?</p><p>Use Archive instead if you want to keep its history. Deletion cannot be undone here.</p>',async()=>change('supply.delete',{id,revision}),'Delete supply');return true;}case 'toolbox-tab':toolboxTab=id;workshopJob=null;render();return true;case 'add-supply':editSupply();return true;case 'edit-supply':editSupply(id);return true;case 'archive-supply':{const s=db.supplies.find(s=>s.id===id),revision=db.revision;modal(s.archived?'Restore toolbox item':'Archive toolbox item','<p>'+esc(s.name)+(s.archived?' will return to your toolbox.':' will be hidden from active items. Its history is retained.')+'</p>',async()=>change('supply.archive',{id,revision}),s.archived?'Restore':'Archive');return true;}case 'item-photo':{const image=await api('file','image');if(image){inventoryPhoto=image.data;refreshItemAppearance();}return true;}case 'item-photo-remove':inventoryPhoto='';refreshItemAppearance();return true;}return false;}
document.addEventListener('change',event=>{const el=event.target;if(el.id==='category'&&$('#part-type-field'))$('#part-type-field').innerHTML=partTypeInput(el.value);if(el.name==='kind'&&$('#consumable-fields'))$('#consumable-fields').hidden=el.value!=='Consumable';if(el.id==='part-category-filter'){partCategory=el.value;partTypeFilter='';if(db.parts.find(p=>p.id===partId)?.category!==partCategory)partId=null;render();}if(el.id==='part-type-filter'){partTypeFilter=el.value;if(partTypeFilter&&db.parts.find(p=>p.id===partId)?.partType!==partTypeFilter)partId=null;render();}if(el.id==='supply-category-filter'){supplyCategory=el.value;render();}if(el.id==='supply-low'){supplyLow=el.checked;render();}if(el.id==='supply-archived'){supplyArchived=el.checked;render();}});
document.addEventListener('input',event=>{if(event.target.id==='supply-search'){supplyQuery=event.target.value;if(local()&&db._view)scheduleView();else $('#supply-results').innerHTML=supplyCards();}});
